ALTER TABLE public.appointments ADD COLUMN appointment_code text NOT NULL DEFAULT ('AG-' || upper(replace(gen_random_uuid()::text, '-', ''))), ADD COLUMN employee_snapshot jsonb;
CREATE UNIQUE INDEX appointments_code_unique ON public.appointments(appointment_code);
UPDATE public.appointments a SET employee_snapshot = jsonb_build_object('full_name',e.full_name,'cpf',e.cpf,'rg',e.rg,'birthplace',e.birthplace,'nationality',e.nationality,'birth_date',e.birth_date,'sex',e.sex,'job_title',coalesce(a.job_title,e.job_title),'occupational_function_id',e.occupational_function_id,'admission_date',e.admission_date,'workplace',e.workplace) FROM public.employees e WHERE e.id=a.employee_id AND a.employee_snapshot IS NULL;
CREATE OR REPLACE FUNCTION public.capture_appointment_employee_snapshot() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.employee_snapshot IS NULL THEN SELECT jsonb_build_object('full_name',e.full_name,'cpf',e.cpf,'rg',e.rg,'birthplace',e.birthplace,'nationality',e.nationality,'birth_date',e.birth_date,'sex',e.sex,'job_title',coalesce(NEW.job_title,e.job_title),'occupational_function_id',e.occupational_function_id,'admission_date',e.admission_date,'workplace',e.workplace) INTO NEW.employee_snapshot FROM public.employees e WHERE e.id=NEW.employee_id; END IF; RETURN NEW; END; $$;
CREATE TRIGGER capture_appointment_employee_snapshot BEFORE INSERT ON public.appointments FOR EACH ROW EXECUTE FUNCTION public.capture_appointment_employee_snapshot();
COMMENT ON COLUMN public.appointments.employee_snapshot IS 'Employee details used for this appointment; editing these does not modify the employee registry or other appointments.';